/* مجتمع بلس — page help, en text (GENERATED by help-wire build_registry.py; lazy chunk "helpcontent-en", merged by help-ui.js). */
(window.MPHelpContentL = window.MPHelpContentL || {}).en = {
  "#/admin/storage|":{"title":"Storage admin","body":"See how much media and file space the server uses, by type.\n“Scan orphans” lists files no post uses anymore, without deleting anything.\nDeletion only happens after you review the list and confirm.","tips":["This page is for moderators only.","Trimming a clip keeps the original; only unused copies are cleaned."]},
  "#/admin/aihub|":{"title":"AI Hub admin","body":"Track AI Hub usage: members linked per provider and request counts.\nPause a provider for now when needed.\nMembers' messages and keys never appear here.","tips":["This page is for moderators only."]},
  "#/aihub|":{"title": "AI Hub", "body": "Link your own AI account and use it right here in Mujtama Plus.\nOpenRouter links in one tap: sign in there and approve; usage is billed to your OpenRouter credits.\nOther providers link with a key from the provider's own page; we store it encrypted and never show it.\nWe don't keep your chats — only a daily request count.", "tips": ["Pick your account for the writing helper under Preferences so it runs without app limits.", "ChatGPT sign-in is waiting on OpenAI's official approval.", "Unlink any account at any time; the key is deleted right away."]},
  "#/home|":{"title":"Home","body":"Posts from people you follow and your communities appear here.\nThe tabs at the top change the feed: For you, Following, Latest, Explore, My communities, and your lists.\nThe stories bar shows stories from people you follow. Tap “What do you want to post?” to write a post.","tips":["Scroll down to load more posts automatically.","Pick “Following” to see only people you follow.","If your feed is empty, follow people and join communities from Explore."]},
  "#/feedprefs|":{"title":"Feed & summaries","body":"Control how your feed looks here.\nYou can keep the feed always in time order with no smart ranking, and customize and reorder the tabs.\nSee what you asked to see more or less of, undo it, and turn on the weekly email.","tips":["From any post's menu, choose “More/Less like this” to teach the feed your taste.","If email is not enabled on the server yet, your choice is saved and sending starts later.","You can also subscribe to the weekly email digest here."]},
  "#/studio|":{"title":"Creator studio","body":"One place for how your posts perform and when they go out.\nThe calendar shows scheduled posts; drag one to change its time.\n“Best time” suggests when your audience is most active.","tips":["Switch the range (7, 28 or 90 days) to see a longer period.","“Advanced analytics” opens more detail.","Start with “Best time” to see when your audience is active."]},
  "#/wallet|":{"title":"Wallet","body":"Your linked Pi account and the history of all your payments.\nEach payment shows its status; tap it to open its receipt.\nA “Testnet” badge means no real money is involved.\nPi payments are not enabled yet. The wallet works as soon as they are.","tips":["Link your Pi account in Settings → Pi Network.","Payments are made inside Pi Browser.","Transfers are reachable from here too."]},
  "#/receipt/|":{"title":"Payment receipt","body":"Details of one payment: amount, memo, status and dates.\nShows the transaction id (txid) with a link to the network explorer.\nYou can copy or share the receipt.","tips":["Keep the txid when contacting support."]},
  "#/mjt|":{"title":"Mujtama Coin (MJT)","body":"An in-app balance you earn through helpful contributions.\nIt is not a coin on any blockchain and cannot be withdrawn or sold.\nThe “How to earn” tab lists sources; rewards have a daily cap shown at the top.\nYou can send MJT to another member within limits shown on the page.","tips":["Transfers are final and not refundable, so check the username.","Turn off “Receive transfers” if you don’t want to receive any.","Buying MJT with Pi is not enabled yet."]},
  "#/points|":{"title":"Contribution points","body":"Earn points for helpful contributions; they raise your level and rank.\nEach kind of contribution has its own points and daily cap, plus an overall daily cap.\nEvery new point adds 1 MJT to your Mujtama Coin balance.\nEngagement from linked or suspicious accounts doesn’t count; points for deleted content are removed.","tips":["Watch “Season campaigns” for point multipliers.","You can hide yourself from the leaderboard.","Members under 18 don’t appear on the leaderboard."]},
  "#/leaderboard|":{"title":"Leaderboard","body":"Members ranked by contribution points.\nChoose all time, this month, or a specific campaign.\nYour own row is highlighted if you’re listed.","tips":["Don’t want to appear? Turn it off on the Points page."]},
  "#/transfers|":{"title":"Pi transfers","body":"Send Pi to another member or request an amount from them.\nHistory shows incoming and outgoing; you can turn off receiving.\n“Limits and protection” explains single and daily limits; large transfers or ones from new accounts may be reviewed first.\nTransfers are not enabled yet; they work once Pi payments are enabled.","tips":["Not available to members under 18.","Double-check the username before sending."]},
  "#/transfers/send|":{"title":"Send Pi","body":"Enter the username, the amount and an optional note.\nReview the details, then confirm the payment in Pi Browser.\nPi transfers are not enabled yet.","tips":["The maximum is shown under “Limits and protection”."]},
  "#/transfers/request|":{"title":"Request a payment","body":"Ask a member for an amount, with an optional reason.\nThey get a notification and can pay or decline.\nThe request expires after the number of days shown on the page.\nNot enabled yet; it works once Pi payments are enabled.","tips":["Track your requests under “Requests”."]},
  "#/transfers/requests|":{"title":"Payment requests","body":"“Incoming”: requests to you — pay or decline them.\n“Outgoing”: your requests to others — you can cancel them.\nNot enabled yet; requests appear here once Pi payments are enabled.","tips":["Don’t pay a request from someone you don’t know."]},
  "#/transfers/|":{"title":"Transfer receipt","body":"Details of one transfer: both members, amount, note and status.\nIf it is “under review”, it arrives once the safety review ends."},
  "#/support/|":{"title":"Creator support page","body":"Support a creator with a tip or a monthly subscription to one of their tiers.\nTip: pick 1, 5, 10 or a custom amount, add a message, optionally anonymous.\nThe page shows the honour roll for the month and all time.\nPi payments are not enabled yet.","tips":["A single tip is at most 100 Pi.","You can renew support up to three days before it ends.","Tips and support aren’t available to members under 18."]},
  "#/creator|":{"title":"Creator settings","body":"Turn on tips and monthly support for your account.\nCreate up to 3 support tiers with prices and benefits.\nYou can set them up now even though Pi payments are not enabled yet.","tips":["Describe each tier’s benefits clearly.","Track your income in “Earnings”."]},
  "#/earnings|":{"title":"Earnings","body":"Your income from tips and support by day, week or month.\nShows gross, fees and net, with a chart.\nLists your top posts and supporters; export to CSV.\nPi payments are not enabled yet.","tips":["Your account statement gathers all your money activity."]},
  "#/me/supporting|":{"title":"Who I support","body":"The creators you support monthly.\nSee the tier and renewal date for each one.\nRenew or cancel from the creator’s page."},
  "#/subs/|":{"title":"Creator subscriptions","body":"Monthly subscription tiers and what each includes.\nSee your status: due, grace period, or scheduled downgrade.\nUpgrades are prorated, downgrades start next cycle, and you can cancel.\nPi payments are not enabled yet.","tips":["Subscribers get the subscriber channel and its badges."]},
  "#/subscribers|":{"title":"My subscribers","body":"Your creator dashboard for monthly subscriptions.\nSee your subscribers and cancellation stats.\nEdit tier benefits and set early-access content.","tips":["Clear benefits reduce cancellations."]},
  "#/me/paid-posts|":{"title":"My paid posts","body":"Your supporters-only and pay-once posts.\nSee unlocks and revenue for each post.\nWhen posting choose: free, supporters only, or pay once with a teaser.\nPi payments are not enabled yet. Paid options stay off until then.","tips":["A good teaser encourages unlocks."]},
  "#/me/purchases|":{"title":"My content purchases","body":"Paid posts you have unlocked.\nYou can request a refund for a purchase here.","tips":["Digital products are under “My purchases” in the digital store."]},
  "#/ads|":{"title":"My ads","body":"Your ethical ad campaigns and the status of each.\nAn ad promotes one of your posts and is labelled “Promoted”.\nTargeting uses only topics, language and country — no personal data.","tips":["Campaigns are reviewed before they run.","Funding campaigns with Pi is not enabled yet."]},
  "#/ads/new|":{"title":"New campaign","body":"Steps: pick a post, then audience, then budget, then review.\nA live audience estimate updates as you target.\nThe campaign is sent for review before it runs.","tips":["Start broad, then narrow down.","Counts under 10 show as “fewer than 10” for privacy."]},
  "#/ads/campaigns/|":{"title":"Campaign dashboard","body":"Campaign performance: impressions, clicks and a daily chart.\nYou can pause, resume or fund it.\nAn impression counts when half the ad is visible for at least a second.\nFunding with Pi is not enabled yet."},
  "#/settings/ads|":{"title":"Ad preferences","body":"Control the ads you see.\nFrom any ad’s menu: “Why am I seeing this?”, hide the ad, or hide the advertiser."},
  "#/market|":{"title":"Community market","body":"Browse members’ items; search and filter by type, condition and price.\nOpen an item to see photos and the seller’s rating, then buy.\nYour payment is held in escrow until you confirm receipt.\nPi payments are not enabled yet. Buying is paused until then.","tips":["List something with “Sell an item”.","Your orders and sales are in “My orders”."]},
  "#/market/item/|":{"title":"Item page","body":"Photos, description, price, and the seller’s card and rating.\nChoose a quantity, then “Buy” to create the order and pay.\nIf buying isn’t possible, the reason shows on the button.\nPi payments are not enabled yet.","tips":["Read the seller’s reviews before buying.","Use the arrow keys to browse photos."]},
  "#/market/new|":{"title":"Sell an item","body":"Add the title, description, price, condition and category.\nUpload 1 to 8 photos and reorder them.\nClear messages tell you if something is missing.","tips":["The first photo is the cover.","Add alt text to your photos."]},
  "#/market/orders|":{"title":"My market orders","body":"Three tabs: purchases, sales, and your listings.\nOpen any order to see and follow its status."},
  "#/market/orders/|":{"title":"Order details","body":"Order steps, timeline and escrow status.\nThe seller ships and delivers; the buyer confirms receipt and the funds are released.\nIf the buyer doesn’t confirm, funds are released automatically some days after delivery.\nYou can chat, review, or open a dispute with evidence.","tips":["Don’t confirm receipt before the item arrives.","Open a dispute before confirming if there’s a problem."]},
  "#/market/seller/|":{"title":"Seller page","body":"The seller’s rating summary and buyer reviews.\nSeller replies to reviews are shown."},
  "#/digital|":{"title":"Digital store","body":"Digital products from members: files, templates and more.\nFilter by type or search; sell, or see your sales and purchases from here.\nPi payments are not enabled yet. Buying is paused until then.","tips":["Try the preview before buying."]},
  "#/digital/p/|":{"title":"Digital product","body":"Cover, file names and sizes, with a preview and sample.\nThe refund policy is shown before you buy.\nYou can report copyright issues or abuse.\nPi payments are not enabled yet."},
  "#/digital/new|":{"title":"Sell a digital product","body":"Add cover images and the files the buyer receives.\nAdd a free preview and set the refund policy.","tips":["Only upload what you own the rights to."]},
  "#/digital/sales|":{"title":"My digital sales","body":"Stats for each product over the last 30 days.\nLicense keys issued to buyers."},
  "#/purchases|":{"title":"My purchases","body":"Digital products you have bought.\nDownload links expire; downloads left and the license key are shown.\nYou can request a refund under the product’s policy.","tips":["Download your files before the link expires."]},
  "#/biz|":{"title":"Businesses accepting Pi","body":"A directory of local businesses that accept Pi.\nSearch, pick a category, and filter: accepts Pi, open now, verified, delivery.\nChoose a city or “Near me”.","tips":["“Accepts Pi” is the owner’s own statement; confirm before paying.","Add your business with “Add a business”."]},
  "#/biz/|":{"title":"Business page","body":"Info, opening hours, photos and reviews.\nContact options, the Pi badge and “open now” status.\nIf it’s yours, tap “This is my business” to claim it.","tips":["You can report wrong information.","Contact options are hidden from members under 18."]},
  "#/biz/new|":{"title":"Add a business","body":"Choose a storefront with a map pin, or a home-based business.\nHome-based businesses show the city only, no address.\nAdd the category, contacts, and whether you accept Pi.","tips":["Add opening hours so “open now” shows."]},
  "#/biz/mine|":{"title":"My businesses","body":"Businesses you own and the ownership claims you submitted.\nOpen one to edit its details."},
  "#/statement|":{"title":"Account statement","body":"All your Pi money activity in one place.\nFilter by date and category, with totals.\nExport CSV and open invoices and documents.","tips":["The annual summary shows the full year month by month."]},
  "#/invoice/|":{"title":"Invoice / document","body":"An invoice, credit note or payout receipt.\nPrint it and save as PDF, or download it as HTML."},
  "#/annual|":{"title":"Annual summary","body":"What you spent, and earned as a creator, over the year.\nBroken down month by month."},
  "#/finance-report|":{"title":"Financial transparency report","body":"A public report of the platform’s aggregate finances.\nNo member’s data is revealed; small numbers are hidden for privacy."},
  "#/creator-program|":{"title":"Verified creators","body":"A programme that verifies serious creators and backs their projects.\nSupport comes from a transparent fund with public figures.","tips":["Open “Support fund” to see grant rounds."]},
  "#/fund|":{"title":"Creator support fund","body":"Grants for verified creators’ projects with public figures: balance, received, awarded, paid.\nOpen a round to see its criteria and dates, then apply or edit.\nA grant page shows the plan, milestones and progress updates.\nDonations and grant payouts are not enabled yet, until Pi payments are.","tips":["You can withdraw your application before the round closes."]},
  "#/post/:id|":{"title":"Post","body":"This page shows the full post with its comments.\nWrite your comment in the bar at the bottom, and tap “Reply” under any comment to answer it.\nSort comments by “Most relevant” or “Latest”, and search inside the discussion when there are many comments.","tips":["Tap “Summarize discussion” for a quick summary of the comments.","On questions, the asker can pick the “Best answer”.","Use “Report” under any comment that breaks the rules."]},
  "#/scheduled|":{"title":"Scheduled posts","body":"Everything you scheduled for later is here: posts, stories, and articles.\nTimes are shown in your time zone, and you can choose another zone for each post.\nYou can change the time, publish now, or cancel the schedule.","tips":["Cancelling a schedule does not delete it; it goes back to your drafts.","Check the time zone before saving if your audience is in another country."]},
  "#/drafts|":{"title":"Drafts","body":"If you close the editor before posting, your writing is saved here automatically.\nDrafts are saved to your account and show on all your devices.\nFor each draft: “Continue” writing, “Schedule” it, or delete it.","tips":["Deleting here is permanent, so check first.","Content you unscheduled also appears here."]},
  "#/series|":{"title":"Series","body":"A series groups your posts and articles in order, so people can follow them episode by episode.\n“My series” shows what you created, and “Following” shows series you follow.\nInside a series you see its episodes and your progress, and you can follow it to get new episodes.","tips":["Tap “New series” to start weekly lessons or a project diary.","You can mute a series' notifications without unfollowing.","The owner sees “Stats” and “Edit”."]},
  "#/explore|":{"title":"Explore","body":"A place to discover what is happening: trends, topics, and active communities.\nYou see trends by place, topics suggested for you, and articles and discussions worth reading.\nIt also has quick links to short videos, voice rooms, and “What you missed today”.","tips":["Tap the search box at the top to search the whole app.","Follow a topic you like to see its posts in your feed."]},
  "#/search|":{"title":"Search","body":"Type what you are looking for to find people, posts, communities, and hashtags.\nUse filters to set result type, date, language, and community.\nYour recent searches appear here, and you can save a search to know when there are new results.","tips":["Remove any search from history, or tap “Clear all”.","Not sure what to search? Try “Trending now” or “Browse topics”."]},
  "#/topic/:slug|":{"title":"Topic","body":"This page gathers everything about one topic.\nIt has active hashtags, editors' picks, topic communities, notable voices, and most-discussed posts.\nTap “Follow topic” to see its posts in your feed.","tips":["No recent posts? Tap “Start the discussion” and write the first one.","Join a topic community to meet people who care about it."]},
  "#/tag/:tag|":{"title":"Hashtag","body":"Shows all posts with this hashtag (#).\nYou see the number of posts and followers, and a summary of what is being said.\nTap “Follow hashtag” to get its posts in your feed.","tips":["Read “What's happening” to understand the topic quickly.","Add the same hashtag to your post to appear here."]},
  "#/trends|":{"title":"Trends","body":"Shows the most talked-about hashtags right now.\nChoose a view: global, by language, by topic, or by community.\nTrends are based on growth speed and number of different people, not just post count.","tips":["“Early rising” shows what started spreading in the last 6 hours.","Tap any hashtag to see its posts."]},
  "#/digest|":{"title":"What you missed today","body":"A summary of the last 24 hours from people you follow, your communities, and your topics.\nIt shows the highlights, comments on your posts, and today's trends, with links to the original posts.\nThe summary is written automatically from post text only.","tips":["Tap any point to open its original post.","You can ask for a weekly email digest in “Feed & summaries”."]},
  "#/interests|":{"title":"Interests","body":"Shows the topics you care about, which shape your feed.\nTap “More” or “Less” for each topic, or ✕ to remove it.\nThe app suggests topics it learned from your activity, and shows what you muted.","tips":["Add suggested topics if they really interest you.","Mute a topic you don't want instead of ignoring it."]},
  "#/library|":{"title":"Saved","body":"What you saved is here, split into: Collections, Read later, and Lists.\nDrag to reorder collections, and add a private note to any item.\n“Read later” shows items you asked to be reminded about.","tips":["From any post's save button, choose “Save and remind me later”.","Offline, you see a saved copy and changes sync when you reconnect.","Save any post from its options menu."]},
  "#/collection/:id|":{"title":"Collection","body":"Shows the items you saved in this collection.\nDrag items to reorder them, or drop them on another folder to move them.\nYou can share, rename, or delete the collection.","tips":["A private collection is only visible to you until you share it.","Deleting a collection deletes everything in it."]},
  "#/sc/:token|":{"title":"Shared collection","body":"This is a collection of posts someone shared with you.\nYou only see posts you are allowed to see.\nTap any post to open it in full.","tips":["If no posts show, they may be private or deleted."]},
  "#/lists|":{"title":"Lists","body":"A list is a group of people whose posts you like to read together.\nTap “New list”, pick a name and description, and make it public or private.\nEach list shows as a tab on Home.","tips":["Make a list for one subject, like “Arab developers”, to read them without noise.","Create a list for a topic you care about."]},
  "#/list/:id|":{"title":"List","body":"Shows posts only from members of this list.\nTap “Add people” and search by name or handle to add them.\nYou can make it public or private, or delete it.","tips":["A private list is only visible to you.","If it's empty, add people who post often."]},
  "#/me|":{"title":"My profile","body":"This is your profile as others see it, with your posts and sections.\nTap “Edit profile” to change your name, bio, photo, and cover.\n“Preview” shows how others see you, and “Profile completion” suggests what's missing.","tips":["Complete your profile so people can find and follow you.","Reputation comes from the quality of your posts, not how many.","Pi support is not enabled yet."]},
  "#/u/:handle|":{"title":"Profile","body":"Shows another person's profile: bio, posts, and followers.\nTap “Follow” to see their posts in your feed, or “Message” to write to them.\nIf the account is private, a follow request is sent and waits for approval.","tips":["The verified badge means the identity is confirmed, not that we endorse their views.","Add them to a list to read them with similar people.","Supporting creators with Pi is not enabled yet."]},
  "#/follows/:handle/:type|":{"title":"Followers & following","body":"Shows who follows this account, or who it follows.\nTap any name to open their profile.\nThe “Follow” button next to each person lets you follow them right away.","tips":["Browse who your favourite people follow to find similar accounts."]},
  "#/settings|":{"title":"Settings","body":"Control your account and what you see here.\n“Manage what you see”: your interests, muted topics and accounts, and blocked people.\nYou'll also find links to appearance, notifications, feed, and your decisions & reports log.","tips":["Unmute or unblock anyone here at any time.","Pi sign-in and payments are not enabled yet."]},
  "#/settings/appearance|":{"title":"Appearance","body":"Change how the app looks.\nPick the theme, dark mode, density, navigation bar, and app icon.\nChanges apply right away.","tips":["OLED dark mode is easier on the eyes at night."]},
  "#/notifications|":{"title":"Notifications","body":"Everything about you is here: likes, comments, follows, mentions, and community news.\nSort by “Top” or “Latest”, and pick a tab to filter by type.\nTap “Mark all as read” to clear the counter.","tips":["Tap any notification to go straight to the post or person.","Change what you receive in “Notification settings”."]},
  "#/notifsettings|":{"title":"Notification settings","body":"Turn on device notifications to get alerts even when the app is closed.\nFor each type, choose how it reaches you: in the app, device notification, or email.\n“Quiet hours” hold device notifications until the period ends; all stay in the notification center.","tips":["On iPhone, add the app to your Home Screen first for notifications to work.","Calls and security alerts can still reach you during quiet hours.","Security alerts can't be turned off, to protect your account."]},
  "#/nsettings|":{"title":"Notification settings","body":"Turn on device notifications to get alerts even when the app is closed.\nFor each type, choose how it reaches you: in the app, device notification, or email.\n“Quiet hours” hold device notifications until the period ends; all stay in the notification center.","tips":["On iPhone, add the app to your Home Screen first for notifications to work.","Calls and security alerts can still reach you during quiet hours.","Security alerts can't be turned off, to protect your account."]},
  "#/emailprefs|":{"title":"Email preferences","body":"Choose which messages reach your email here.\nYou need to confirm your email first, and you can resend the confirmation link.\nYou can unsubscribe or resubscribe at any time.","tips":["If email sending isn't enabled on the server yet, your choices are saved for later.","Change your email from the Security page."]},
  "#/messages|":{"title":"Messages","body":"Your private chats and groups are here.\nThe “Requests” tab has messages from people you don't follow; they won't know you read them until you accept.\nTap “New message” to start a chat, or “New group” to create a group.","tips":["Search chats by name or handle.","Private chats can be end-to-end encrypted.","You can also reach “Linked devices” from here."]},
  "#/chat/:id|":{"title":"Chat","body":"Type your message at the bottom and tap send.\nIf the chat is end-to-end encrypted, nobody else can read it, not even Mujtama+.\nIf it's a message request, tap “Accept” or delete it without telling the sender.","tips":["Tap “Info” for details, members, and disappearing messages.","If it isn't encrypted, tap “Turn on encryption”.","Tap “Older messages” to see earlier ones."]},
  "#/chatinfo/:id|":{"title":"Chat info","body":"Shows the chat or group details and members.\nFrom here you turn on encryption, verify the safety code, and set disappearing messages.\nIn groups you can add members, rename, or leave the group.","tips":["Disappearing messages vanish for everyone after the chosen time.","In a group, only admins change the disappearing time.","End-to-end encryption is currently for private chats only."]},
  "#/newgroup|":{"title":"New group","body":"Type a group name and choose its members.\nPeople who accept your messages are added directly; people who don't follow you get an invite as a request.\nTap “Create group” to start.","tips":["Some people may not be added because of their privacy settings.","Pick a clear name that explains the group's purpose."]},
  "#/message-requests|":{"title":"Message requests","body":"This page takes you to the “Requests” tab in Messages.\nIt holds messages from people you don't follow; you won't get notifications from them until you accept.","tips":["The sender won't know you read it until you accept."]},
  "#/safety/:id|":{"title":"Safety code","body":"Each encrypted chat has a numeric safety code.\nCompare the numbers with the other person face to face or on a call, or scan the QR code on their device.\nIf they match, mark it “Verified”; only you two can read your messages.","tips":["If the code changed, they probably added a new device; verify again before sharing anything sensitive.","The code appears once you both turn on encryption."]},
  "#/e2ee|":{"title":"End-to-end encryption","body":"This page explains how your messages are protected.\nYour device creates a secret key that never leaves it, and each message is locked before it's sent.\nThe server passes the locked message on without opening it; it only knows a message was sent and when.","tips":["Verify the safety code with the person you chat with.","If you lose your phone, unlink it from another linked device.","Groups are protected in transit; full encryption is for private chats for now."]},
  "#/devices|":{"title":"Linked devices","body":"Shows every device you signed in on that turned on encryption; each has its own key.\nTo link a new device, sign in on it and open Messages; it appears here automatically.\nTap “Unlink” for any device you don't recognise.","tips":["Up to 10 devices.","An unlinked device no longer receives your encrypted messages."]},
  "#/calls|":{"title":"Calls","body":"Your call history: incoming, outgoing, and missed.\nTap the call button next to any call to call back.","tips":["You can call anyone from their chat or profile."]},
  "#/menu|":{"title":"More","body":"All Mujtama+ sections in one place.\nSearch features and settings from the box at the top.\nYou see your shortcuts, recently visited pages, then all sections.","tips":["Tap “View your profile” for quick access to your account.","Pi-related features show a “Not enabled yet” label."]},
  "#/town|":{"title":"Your city","body":"Your city sits at the top of your profile: every building is a door to its own section.\nTap a building and your character walks to its door and goes in, or tap a street to walk there.","tips":["The glowing line shows the shortest way.","When you come back, your character waits at the door of the last building you entered."]},
  "#/shorts|":{"title":"Clips","body":"Short video clips shown one after another.\nSwipe up or down to move between videos.\nEach video has buttons: Like, Comments, and Share.","tips":["Tap “Back” to return to Explore.","Stories are in the bar at the top of Home; add one with “Add story”."]},
  "#/clips|":{"title":"Clips","body":"Short video clips shown one after another.\nSwipe up or down to move between videos.\nEach video has buttons: Like, Comments, and Share.","tips":["Tap “Back” to return to Explore.","Stories are in the bar at the top of Home; add one with “Add story”.","When creating a clip you can trim its start and end before posting; an interrupted upload resumes where it stopped."]},
  "#/clips/challenges|":{"title":"Vidtik challenges","body":"A new challenge every week, built around one hashtag.\nPost a clip with that hashtag during the challenge and it enters automatically.\nWhen it ends, the top three winners are shown.","tips":["Tap a challenge to see its clips and your rank.","Ranking counts likes, comments, shares and full views."]},
  "#/clips/drafts|":{"title":"Vidtik drafts","body":"Clips you uploaded and saved without posting.\nOpen a draft to finish the caption, cover and link, then post it or schedule it.\nYour drafts are private.","tips":["Save a draft from the Vidtik editor with “Save draft”.","You can keep up to 20 drafts."]},
  "#/clips/stats/:id|":{"title":"Video stats","body":"Your clip's numbers: how many people watched it, how many finished it, average watch time and engagement.\nYou also see where viewers came from and views over the last 14 days.\nOnly you can see this page.","tips":["Your own views don't count.","“Finished” means they watched at least 90% of the clip."]},
  "#/clips/challenge/:id|":{"title":"Weekly challenge","body":"Here is the challenge idea, its hashtag and the time left.\nTap “Join with a clip” to open the editor with the hashtag already in the caption.\n“Top” ranks each creator’s best clip; “Newest” shows every clip.","tips":["You can enter more than one clip; your best one counts for your rank.","A deleted or private clip leaves the challenge."]},
  "#/rooms|":{"title":"Voice rooms","body":"Live audio discussion rooms.\nSee rooms that are live now, and tap any room to join and listen.\nTap “New voice room”, type the topic, then “Start now”.","tips":["Your followers get a notification when your room starts.","Live rooms need an internet connection."]},
  "#/room/:id|":{"title":"Voice room","body":"You are inside a live voice room.\nSpeakers are at the top, listeners below them.\nRaise your hand to ask to speak; the host can invite you to become a speaker.","tips":["Once you're a speaker, tap “Turn on mic” to talk.","The host can record or end the room for everyone.","After the room ends, “Listen to recording” may be available."]},
  "#/communities|":{"title":"Communities","body":"Your communities, suggestions for you, and the full directory.\nSearch by name, pick a category, and sort by most active, largest or newest.\nOpen a community to see its posts, then tap “Join” to become a member.","tips":["Private communities need moderator approval, so you'll see “Pending approval”.","“Create” starts a new community that you own."]},
  "#/c/:id|posts":{"title":"Community page","body":"At the top: the community's name, type, member count and this week's activity.\nTabs: Posts, Knowledge, Events, Members, About, and Market if the community turned it on.\nIn “Posts”, channels sit on the side, pinned posts on top, then the feed.\nThe “…” menu has share, invite link, rules, notifications, appeals and leave.","tips":["Use the search box under the card to search inside the community.","Tap a tag to filter posts, or a channel to see only its posts.","If asked, accept the rules first so you can post."]},
  "#/c/:id|channels":{"title":"Channels and categories","body":"Channels split the community into topics and are grouped into categories on the side.\nChoose “All” for every post, or a channel to read and write in it.\nUnder the channel name you'll see its notes: archived, slow mode, reviewed before showing, or mods-only posting.","tips":["A lock next to a channel means it's for members or specific roles.","The number on a channel counts new unread posts.","Archived channels are read-only."]},
  "#/c/:id/knowledge|":{"title":"Knowledge","body":"The community's know-how: FAQ, wiki pages, Q&A and a resource library.\nTap “Ask” to post a question; similar questions are suggested before you post.\nAdd a useful link to the library and vote up the best resources.","tips":["The “Unanswered” filter shows questions waiting for help.","“✓ Solved” means the asker accepted an answer."]},
  "#/wiki/:id/:slug|":{"title":"Wiki page","body":"A knowledge page members write together.\nThe side shows all wiki pages and this page's headings for quick jumps.\n“Edit” to change it, “History” to see past versions and who edited.","tips":["A locked page can only be edited by the moderation team.","Muted or banned members can't edit."]},
  "#/c/:id/events|":{"title":"Community events","body":"Upcoming events in this community: meetups, workshops and live streams.\nTap an event to see details and book your seat.\nMembers can create one with “New event”.","tips":["Join the community to hear about new events.","Event tickets in Pi: “Not active yet”."]},
  "#/c/:id/market|":{"title":"Community market","body":"Market listings linked to this community, in one place.\nThis tab only shows if the community's owner or admins turned it on.","tips":["Tap a listing to open it in the market.","Pi payments: “Not active yet”."]},
  "#/c/:id/members|":{"title":"Community members","body":"The member list with join dates and moderator roles.\nSearch by name or username, and filter: All, Moderators, New, Top.","tips":["Tap a member to open their profile.","Moderators see a “…” button next to a member to take action."]},
  "#/c/:id/about|":{"title":"About and rules","body":"The community's numbered rules, some marked “Warning” or “Serious violation”.\nAlso the moderation team, partner communities, challenges and creation date.\nWhen you join you may see a welcome message and getting-started steps.","tips":["Some communities ask you to accept the rules before your first post.","Getting-started steps complete on their own, like your first intro post.","“Invite link” to invite friends."]},
  "#/c/:id/notify|":{"title":"Community notifications","body":"Choose what you get from this community: everything, highlights only (announcements and mentions), or nothing.\nTurn on “Daily digest” for one message a day with the count of new posts.\n“Timed mute” pauses notifications for a while, then they come back on their own.","tips":["Decisions about you, your accepted request and event reminders always reach you.","Open it from the “…” menu on the community page."]},
  "#/cappeal/:id|":{"title":"My decisions and appeals","body":"Moderation decisions about you in this community: warning, mute, ban or removed post.\nPick the decision, explain calmly and clearly, then wait for the result.\nA moderator senior to the one who decided reviews it, and you're notified.","tips":["An accepted appeal lifts the penalty or restores the post.","No decisions listed means your record is clean.","“Automatic decision” means automod made it."]},
  "#/join/:code|":{"title":"Join invitation","body":"You opened a community invite: see its name, description, members and who invited you.\nTap “Join now”; the community may ask questions or need approval.","tips":["If you're already a member you go straight in.","Invite links can expire or be revoked."]},
  "#/events|":{"title":"Events","body":"Upcoming events from your communities and people you follow, by date.\nTap “Event” to create one and invite your followers.","tips":["Tap any event to book a seat or add it to your calendar.","Times show in your time zone."]},
  "#/event/:id|":{"title":"Event page","body":"Date, place, map and stream link if any, with a countdown to the start.\nBook your seat; if it's full you join the waitlist and we tell you when a seat frees up.\n“My ticket” shows a QR code to present at the door.","tips":["“Add to calendar” saves it to your phone's calendar.","Organisers check people in by scanning the code and see the attendee list.","Pi tickets: “Not active yet”."]},
  "#/cadmin|":{"title":"Communities I manage","body":"Every community you own or moderate, with your role and member count.\nThe number beside a community is what's waiting for review.\nTap one to open its admin panel.","tips":["An ownership transfer request to you shows at the top.","Not managing any? Create one from “Communities”."]},
  "#/cadmin/:id|home":{"title":"Community admin panel","body":"Your community's status and what needs you now: join requests, posts awaiting approval, reports.\nAlso suggested setup steps and recent actions.","tips":["Locked sections aren't allowed for your role.","Search settings from the box in the menu."]},
  "#/cadmin/:id|general":{"title":"General and identity","body":"Name, description, directory category, and look: cover, icon and colour.\nPost tags members pick when posting.\nPosting rules: links, media, commercial content, post approval and the smart moderation helper.","tips":["Name and description are owner-only.","Save before leaving the section."]},
  "#/cadmin/:id|privacy":{"title":"Privacy and membership","body":"Community type: public (instant join), private (request approved by mods) or invite-only.\nReview join requests and add questions whose answers come with the request.\nInvite links with a label, limit and expiry, plus direct invites by username.","tips":["Only the owner changes the type; current members stay.","An invite link can be revoked any time."]},
  "#/cadmin/:id|members":{"title":"Members","body":"Search members and filter: All, Team, Members, Muted, Banned.\nFrom each member: change rank or roles, warn, mute or ban.","tips":["You can't act on someone at your rank or above.","CSV export is available to role managers."]},
  "#/cadmin/:id|roles":{"title":"Roles and permissions","body":"Fixed ranks set the order: owner, admin, moderator, member.\nCreate custom roles like “Greeter” or “Wiki editor” that add permissions on top of member.","tips":["Start from a ready template.","Nobody can grant a permission they don't have, or owner permissions."]},
  "#/cadmin/:id|rules":{"title":"Rules and welcome","body":"Write numbered rules: short title, optional explanation and severity.\nA welcome message and getting-started steps for newcomers, plus the channel they land in.\nPreview the newcomer experience and see how many finished the steps.","tips":["You can require accepting the rules before a first post.","A step with “introduce yourself” completes on the first post."]},
  "#/cadmin/:id|channels":{"title":"Channels and categories","body":"Create channels and arrange them into categories with arrows or drag.\nPer channel: who sees and posts, slow mode, post review and allowed types.\nDeleting archives by default: posts stay readable.","tips":["Start with an announcements channel and a discussion one.","Up to 50 channels per community."]},
  "#/cadmin/:id|content":{"title":"Content, pins and announcements","body":"Choose allowed post types; text is always allowed.\nPin up to 5 posts on top and 3 per channel, with optional auto-expiry.\nAn announcement is a bar on top of the community page and can notify once a day.","tips":["An important announcement is highlighted in the alert colour.","Each channel can narrow the types further."]},
  "#/cadmin/:id|knowledge":{"title":"Knowledge base","body":"Organise wiki pages into sections and lock what members shouldn't edit.\nAdd FAQs and follow recent edits.\nA page can be published publicly in the open knowledge library.","tips":["Start with a “Start here” page explaining the community and rules.","Deleting a page is permanent."]},
  "#/cadmin/:id|events":{"title":"Events","body":"Upcoming and past community events with attendance and waitlist.\nPick the default reminder: 24 hours or 1 hour before the start.\nCopy the community calendar link so members can subscribe in their calendar app.","tips":["“New event” for a meetup, workshop or stream.","Pi tickets: “Not active yet”."]},
  "#/cadmin/:id|moderation":{"title":"Moderation","body":"Queue: posts awaiting approval and reports; approve or reject, remove content or dismiss.\nTap “I'll take it” so two mods don't handle the same item, and select several for one decision.\nOther tabs: Appeals, Macros (saved replies), Log, Alerts.\nA member's card shows their auto guard warnings; if they are stopped, tap “Lift the stop” to let them write again.","tips":["An appeal is decided by a moderator other than the one who decided.","“Abuse %” is an automatic estimate of the text's harshness.","Every decision shows in the log with its reason."]},
  "#/cadmin/:id|automod":{"title":"Automod","body":"Rules that run on their own: banned words, links, repeats, too many emoji or mentions, and abusive content.\nOn a match: send to review or reject the post.\nThe penalty ladder applies an automatic penalty when a member keeps breaking rules.\n“Auto guard” (off until you turn it on): removes banned text at once, warns and briefly mutes the member, and after the last warning stops them until a moderator lifts it. “Recommended setup” fills the fields; “Test the guard” checks a text.","tips":["Start from a preset, then adjust.","“Test the rule” to try a text before turning it on.","Moderators are exempt, and members can appeal."]},
  "#/cadmin/:id|insights":{"title":"Insights","body":"Growth and engagement: active members, daily activity, net growth and newcomer retention.\nBest time to post, top posts and contributors, channel activity.\nInvite funnel, moderation health and community health.","tips":["Today's numbers update live and are reconciled nightly.","Export includes aggregated numbers; member data is owner-only."]},
  "#/cadmin/:id|growth":{"title":"Growth and partnerships","body":"Invite links with a QR code, and how many joined through each.\nAdd partner communities shown in “About”.\nCreate challenges with a hashtag members post under.","tips":["Revoke any invite link you no longer want.","A live challenge shows above the community's posts."]},
  "#/cadmin/:id|integrations":{"title":"Integrations","body":"Install bots by app ID and send community events to your server via signed webhooks.\nLink a study group or halaqa, and turn on the market tab.\nMJT rewards for accepted posts and answers, paid from the owner's wallet with a daily cap.\nPi features (paid membership, tips, tickets, fund) are shown: “Not active yet”.","tips":["“Delivery log” shows each webhook's result.","Rewards are reversed if content is removed; no new coins are minted."]},
  "#/cadmin/:id|health":{"title":"Community health","body":"A health score built from activity, retention and moderation.\nDaily active members, 30-day newcomer retention, answered questions and review queue, with recommendations.","tips":["Follow the recommendations to raise the score."]},
  "#/cadmin/:id|danger":{"title":"Danger zone","body":"Pause posting during a spam wave: members stop posting, moderators still can.\nExport community data, and transfer ownership to an admin who accepts within 72 hours.\nArchiving makes the community read-only; you can restore it any time.","tips":["Permanent deletion isn't available; request it via “Support tickets”.","Full export is owner-only."]},
  "#/study|":{"title":"Study groups & circles","body":"Study groups and Quran circles; each group is a full community with study tools.\nSessions, attendance, assignments, goals and recitation records.\nAn existing community can become a study group without changing.","tips":["A session opens a voice room for group members only.","Add a personal goal you track yourself."]},
  "#/courses|":{"title":"Courses","body":"Courses you take at your own pace, lesson by lesson.\nTrack your progress and return to any lesson anytime.\nYou can create a course and follow its learners.","tips":["A course can lead to an exam and a certificate."]},
  "#/exams|":{"title":"Exams","body":"Exams are graded on the server, not on your device.\nYou see your result after submitting; passing earns a certificate.\nAuthorised members can create a new exam.","tips":["Read the instructions before you start."]},
  "#/certificates|":{"title":"My certificates","body":"All your certificates in one place, digitally signed.\nEach certificate has a verification code and a QR code.","tips":["Share the code so anyone can verify it."]},
  "#/mentor-certs|":{"title":"Completion certificates","body":"Give your mentee a signed completion certificate after at least one completed session.\nAnyone can verify it by its code, and the mentee can print it from the certificate page.","tips":["For a minor, the certificate shows the first name and initial only."]},
  "#/verify-cert|":{"title":"Verify a certificate","body":"Enter the certificate code or scan its QR code.\nYou see whether it is valid and its details.","tips":["Verification works without the holder signing in."]},
  "#/knowledge|":{"title":"Knowledge library","body":"Open knowledge articles written by members.\nEvery new version is reviewed before it is published.\nSearch by category or tag, and see each article’s version history.","tips":["Choose the article’s licence when writing.","Find your contributions under “My contributions”."]},
  "#/mentors|":{"title": "Mentoring", "body": "Sessions with experienced people: find a mentor and book a slot.\nFollow your sessions and requests in the tabs.\nSessions show in your time zone and can be rated afterwards.", "tips": ["“Suggest a mentor” helps you choose.", "The “Resources” section on a mentor’s page shows their links and notes; some appear only to their mentees after the first session."]},
  "#/mentoring|":{"title":"Mentor dashboard","body":"Share your experience as a mentor.\nSet your available slots and receive requests and bookings.","tips":["Keep your topics updated so the right people find you."]},
  "#/mentoring|profile":{"title": "Mentor dashboard — Profile", "body": "Edit your mentor profile and who sees each part, then try “Preview as”.\nIn “Resources” add links, files and notes (up to 30) and order them with the up and down buttons.\n“My mentees only” is seen by people who booked a session with you and their guardians; “Everyone” by anyone who can see your page.", "tips": ["Only links starting with https:// are accepted.", "Links open in a new tab."]},
  "#/mentoring|insights":{"title":"Mentor dashboard — My insights","body":"Your mentor numbers in one place: average rating, median time to answer requests, no-show rate and how many learners came back.\nThe bars show your completed sessions per month over the last 6 months.\nOnly you can see these numbers.","tips":["Answering requests quickly helps learners choose you.","Confirm sessions or mark them “no-show” to keep the numbers accurate."]},
  "#/cv|":{"title":"My professional profile","body":"Your CV: experience, skills and work.\nYou control who can see your professional profile.\nIt appears in the talent directory according to your settings.","tips":["Add past work to strengthen your profile."]},
  "#/talent|":{"title":"Talent directory","body":"Find skilled people by skill or city.\nOnly profiles their owners chose to show appear here.","tips":["Open a profile to see experience and reviews."]},
  "#/jobs|":{"title":"Jobs & freelance","body":"Job offers and freelance projects in one place.\nApply and track your applications, or post your own listing.\nNew listings are reviewed before they appear.","tips":["Complete your professional profile before applying."]},
  "#/application/|":{"title":"Application","body":"Details and status of your application to a job.\nFollow messages and updates here.","tips":["An accepted application can become a contract."]},
  "#/contracts|":{"title":"Contracts","body":"Freelance contracts with clear milestones and deliveries.\nFollow each milestone until delivery and approval.\nIf there is a disagreement, a dispute can be opened for moderators.\nPi payments are not enabled yet.","tips":["After a contract is complete you can review the other party."]},
  "#/teams|":{"title":"Teams & projects","body":"A workspace for your team: tasks, files, discussions and updates.\nCreate a team and invite members.","tips":["Assign tasks so everyone knows their role."]},
  "#/reviews|":{"title":"Professional reviews","body":"Review people you worked with and follow your professional reputation.\nReviews come only from completed contracts.","tips":["A fair, specific review helps everyone."]},
  "#/collabs|":{"title":"Collaborations & sponsorships","body":"Agreements between creators and brands, clearly disclosed.\nA sponsored post carries the partnership label.\nDiscover creators, send a collaboration offer or follow your campaigns.","tips":["Seen an undisclosed ad? You can report it."]},
  "#/nearby|":{"title":"Nearby","body":"Places and activity around you, using an approximate area.\nYour exact location is not shown to anyone.","tips":["Add a place so others benefit."]},
  "#/places|":{"title":"My places","body":"Places you added and your favourites.\nEdit your place whenever needed.","tips":["New places are reviewed."]},
  "#/cities|":{"title":"Cities","body":"Browse places in each city.\nPick a city to see what is there.","tips":["Handy when travelling."]},
  "#/developers|":{"title":"Developer portal","body":"Create your apps and get API keys.\nManage scopes, webhooks and bots for each app.\nRevoke apps connected to your account anytime.","tips":["A secret key is shown only once, so keep it safe.","Interactive docs are under “Developer docs”."]},
  "#/wellbeing|":{"title":"Digital wellbeing","body":"Your daily usage is measured on your device only.\nTurn on break reminders and a daily limit.\nYou can hide counts and turn on focus mode.","tips":["Focus mode stops infinite scrolling.","This feature is free for everyone."]},
  "#/hijri|":{"title":"Hijri calendar","body":"Today’s date in Hijri and Gregorian, and a full month view.\nOccasions and seasons with a countdown, plus a date converter.\nIn its settings you can show Hijri dates across the app.","tips":["Tap a season for its reminders and days.","You can add it to your calendar app (iCal)."]},
  "#/ai|":{"title":"Mujtama+ AI","body":"An optional monthly subscription for machine translation and the AI assistant.\nThe assistant suggests better wording for posts and comments; nothing applies without your tap.\nThe app interface in every language is free for everyone.\nPi payments are not enabled yet.","tips":["Translation preferences are in Settings → Translation."]},
  "#/giving|":{"title":"Giving & volunteering","body":"Transparent charity campaigns and volunteering from verified organisations.\nEach campaign page shows the goal, total raised, spending and receipts.\nThe “My giving” tab gathers your participation.\nPi payments are not enabled yet.","tips":["Volunteering is available now without payment.","Your organisation can register as a charity."]},
  "#/studio|overview":{"title":"Studio — Overview","body":"A quick summary of your content and recent performance.\nJump to the other tools from here.","tips":["Check it once a week."]},
  "#/studio|calendar":{"title":"Studio — Calendar","body":"Your scheduled and published posts on a calendar.\nPlan the coming days at a glance.","tips":["Leave gaps between your posts."]},
  "#/studio|best":{"title":"Studio — Best time","body":"When your audience engages most.\nCalculated from engagement on your past posts.","tips":["Schedule your post at one of these times."]},
  "#/studio|recycle":{"title":"Studio — Repost","body":"Past posts that did well and can be shared again.\nRepost as is or after editing.","tips":["Add a fresh touch before reposting."]},
  "#/studio|templates":{"title":"Studio — Templates","body":"Ready templates to start a post from.\nSave time on recurring posts.","tips":["Edit the template before posting."]},
  "#/studio|weekly":{"title":"Studio — Weekly report","body":"Your week in summary: what you posted and how people engaged.\nCompare with the previous week.","tips":["Use it to plan next week."]},
  "#/admin|":{"title":"Admin panel","body":"All admin tools in one place.\nPick a card to open the admin tool you need.","tips":["This page is for admins only."]},
  "#/admin/pi|":{"title":"Pi admin","body":"Follow Pi payments and their status.\nFinancial reports and reconciliation are reachable from here.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/mjt|":{"title":"MJT admin","body":"Manage the in-app “Mujtama Coin” (MJT) balance and its history.\nEvery change is recorded in the log.","tips":["This page is for admins only."]},
  "#/admin/points|":{"title":"Points admin","body":"Manage contribution points and member levels.\nReview the log before any change.","tips":["This page is for admins only."]},
  "#/admin/tips|":{"title":"Pending tips","body":"Tips pending review.\nApprove or reject each tip after checking.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/transfers|":{"title":"Held transfers","body":"Member-to-member transfers held for review.\nDecide to release or cancel them.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/paid|":{"title":"Paid content refunds","body":"Refund requests for paid posts and content.\nReview each request and decide.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/market|":{"title":"Market disputes","body":"Disputes between sellers and buyers in the market.\nRead the order and messages before deciding.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/digital|":{"title":"Digital products admin","body":"Review digital products and reports about them.\nSuspend a violating product when needed.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/biz|":{"title":"Local business admin","body":"Review registered local businesses.\nCheck details before approving.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/finance|":{"title":"Financial reports & reconciliation","body":"Reconcile the internal ledger with Pi payments.\nPlus the platform’s annual reports.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/pricing|":{"title":"Prices & fees","body":"Every paid item with its current price, source and scheduled changes.\nA suggested price is only shown; applying it needs explicit confirmation.\nA full history of every change.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/revenue|":{"title":"Revenue & costs","body":"Revenue by stream and period, plus costs and margin.\nData can be exported as CSV.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/pi-activation|":{"title":"Pi activation","body":"Steps to activate Pi features on the platform.\nAll Pi-related features stay visible as “not enabled yet” until activation.","tips":["This page is for admins only."]},
  "#/admin/activation|":{"title":"Activation hub","body":"One view of how ready features are for activation.\nAnd a link to the Pi activation page.","tips":["This page is for admins only."]},
  "#/admin/ads|":{"title":"Ads review","body":"Ad campaigns waiting for review.\nApprove a compliant campaign or reject it with a reason.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/creator-program|":{"title":"Creators & fund admin","body":"Review verified-creator program applications.\nAnd manage support-fund rounds and grants.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/charity|":{"title":"Giving admin","body":"Review charities, campaigns and volunteering opportunities.\nVerification is required before a campaign appears.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/collabs|":{"title":"Collaborations moderation","body":"Oversee collaborations and partnership disclosure.\nAnd review reports of undisclosed ads.","tips":["This page is for admins only."]},
  "#/admin/pro|":{"title":"Professional profiles moderation","body":"Review reported professional profiles.\nHide a violating one with a reason.","tips":["This page is for admins only."]},
  "#/admin/jobs|":{"title":"Jobs review","body":"Job and freelance listings waiting for review.\nApprove a sound listing or reject it.","tips":["This page is for admins only."]},
  "#/admin/contracts|":{"title":"Contract disputes","body":"Open disputes on freelance contracts.\nCheck milestones and deliveries before deciding.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/reviews|":{"title":"Professional reviews admin","body":"Review reported professional reviews.\nRemove only those that break the policies.","tips":["This page is for admins only."]},
  "#/admin/mentors|":{"title":"Mentoring admin","body":"Review mentors and mentoring sessions.\nAnd handle reports.","tips":["This page is for admins only."]},
  "#/admin/knowledge|":{"title":"Knowledge library admin","body":"Manage the knowledge library and its reviewers.\nAnd follow reports on articles.","tips":["This page is for admins only."]},
  "#/admin/places|":{"title":"Places review","body":"New and edited places waiting for review.\nApprove a correct place or reject it.","tips":["This page is for admins only."]},
  "#/admin/hijri|":{"title":"Moon-sighting announcements","body":"Record moon-sighting announcements.\nThey correct Hijri calendar dates in the app.","tips":["This page is for admins only."]},
  "#/admin/ai|":{"title":"AI admin","body":"Settings for machine translation and the AI assistant.\nAnd the “Mujtama+ AI” subscription.\nPi payments are not enabled yet.","tips":["This page is for admins only."]},
  "#/admin/i18n|":{"title":"Interface text admin","body":"Interface text in Arabic and English.\nFix a translation or complete missing ones.","tips":["This page is for admins only."]},
  "#/admin/a11y|":{"title":"Periodic accessibility audit","body":"Results of the app’s periodic accessibility check.\nThe “Run check now” button runs it again immediately.","tips":["This page is for admins only."]},
  "#/admin/beta|":{"title":"Beta admin","body":"Manage beta waves and feedback.\nTabs: Waves, Board, Dashboard, Feature flags.","tips":["This page is for admins only."]},
  "#/settings/display|":{"title":"Display & accessibility","body":"Adjust font size, high contrast, dyslexia mode, and line and word spacing.\nReduce motion, underline links, use a stronger focus ring, and turn video captions on by default.\nSaved on your device, and in your account when you are signed in.","tips":["Dyslexia mode widens spacing without breaking Arabic letter joins.","Press j and k to move between posts with the keyboard."]},
  "#/a11y/captions/:id|":{"title":"Caption editor","body":"Add captions to a video you posted.\nCaptions are saved as WebVTT and shown to people who turn captions on.","tips":["Captions help deaf viewers and anyone watching without sound."]},
  "#/about|":{"title":"About Mujtama+","body":"An Arabic social platform: real communities, respectful conversation, and full control of your privacy.\nSpecial protection for minors, human review of reports, and download your data or delete your account anytime.\nFull Arabic interface plus English. Pi features are not active yet.","tips":["From here you can reach the waitlist, the ambassador program and the help center."]},
  "#/account-log|":{"title":"My account decisions","body":"Moderation decisions on your account and content, each with its reason.\nYou can appeal any decision you think is wrong from the same form.","tips":["In your appeal, explain clearly what the decision missed."]},
  "#/age|":{"title":"Age & sensitive content","body":"Enter or correct your birth date; nobody sees it and no ID photo is needed.\nUnder 18, you see the protections on your account here; they lift automatically when you come of age.\nChoose how sensitive content appears: covered, shown directly (adults only), or hidden.","tips":["Raising an age from under 18 to 18 or over needs a safety team review."]},
  "#/ambassadors|":{"title":"Community ambassadors","body":"Ambassadors are members who welcome newcomers and spread respectful conversation.\nApply and follow your status here; once accepted you get a badge and a personal referral link.\nSee stats on who joined through you, and create invite codes when sign-up is invite-only.","tips":["Sign in first to apply.","Copy your referral link and share it with people you know."]},
  "#/analytics|":{"title":"Creator analytics","body":"An overview of your performance versus the previous period, with daily views and engagement.\nTabs for audience, per-post performance and best time to post, earnings, and comparing two periods.\nPick 7, 28, 90 or 365 days or a custom range, and export any report as CSV.","tips":["Audience demographics are shown only in aggregate to protect privacy.","Pi earnings are not active yet."]},
  "#/app|":{"title":"The app","body":"Install Mujtama+ on your device to use it as an app, or follow the “Add to Home Screen” steps on iPhone.\nSee notification status on this device, drafts waiting while offline, and the version.\n“Check for updates” fetches the latest version without an app store.","tips":["On iPhone, install the app first, then turn on notifications inside it."]},
  "#/beta|":{"title":"My beta","body":"If you are a beta tester, see your wave here and choose whether the tester badge shows on your profile.\nYou have personal invite codes with a quota, plus your feedback and the team’s replies.\nThe floating “Feedback” button sends a bug or idea with an optional screenshot.","tips":["Open any feedback item to follow its thread."]},
  "#/compliance|":{"title":"Compliance & data protection (admin)","body":"Admin only: the data-subject request queue with deadlines; complete, extend or reject with a reason.\nBreach log with the 72-hour clock for notifying the authority when a breach may harm data subjects.\nData retention rules (preview, then enforce) and generating transparency reports.","tips":["This is engineering support for compliance, not legal advice."]},
  "#/email-prefs|":{"title":"Email preferences","body":"Choose how often the email digest arrives, and your transactional alerts.\nYou can unsubscribe from all emails, with an undo option.","tips":["In-app and push notifications are set in notification settings."]},
  "#/family|":{"title":"Family settings","body":"A transparent link between an adult guardian and an under-18 account, with consent from both and mutual follow.\nThe guardian can only make settings stricter, and the account holder is told of every change.\nThe account holder sees everything the guardian sees, with the activity log.","tips":["Add a link by username; either side can end it."]},
  "#/faq|":{"title":"Help center & FAQ","body":"Search the FAQ and help articles, and open any article to read it in full.\nIf you can’t find the answer, open a support ticket and the team replies there.","tips":["Type one clear word in search for sharper results."]},
  "#/help|":{"title":"Help & safety center","body":"Quick guides on blocking, muting and protection mode, with links to your tools and content policies.\nSupport and emergency contacts: official numbers verified at their source, for awareness only.","tips":["In immediate danger? Contact emergency services directly.","For serious cases on the platform, use “Urgent report”."]},
  "#/integrity|":{"title":"Your trust center","body":"Your account’s trust signals and what they mean, including the transparent “new account” badge.\nOptionally verify your phone number with a code to raise your account’s trust.\nPi identity verification (KYC) is not active yet.","tips":["The device signal is sent only as hashes, never readable data."]},
  "#/investigations|":{"title":"Investigations (staff)","body":"Staff only: the review queue for fake accounts and coordinated networks.\nEach case shows evidence and the relationship graph, with soft limits and hiding fake followers.\nThe account page gathers its signals, and you can run a manual scan.","tips":["Review all evidence before applying any limit."]},
  "#/legal|":{"title":"Terms & privacy","body":"Terms and privacy policy in plain language, with an “In short” box and a table of contents.\nSee the version and effective date, plus the processing register showing how your data is used.","tips":["Transparency reports are also available from settings."]},
  "#/my-reports|":{"title":"My reports","body":"Every report you sent and its status on a timeline: received, under review, decision.\nKnow when the review finished and what was decided.","tips":["Report from the menu of any post or account."]},
  "#/mydata|":{"title":"My data & privacy","body":"Download a copy of your data as JSON or ZIP, and manage your consent for each purpose.\nSend a correction, objection or question request and follow its status.\nDelete your account with a grace period during which you can cancel.","tips":["Your account decisions log is reachable from here too."]},
  "#/orgs|":{"title":"Organizations","body":"Create an account for your company or organization, and add your team to post as it without sharing a password.\nAccept or decline join invites; each member has a set role.\nThe organization page shows followers, last-30-days activity and members.","tips":["Verify the organization to show the “Organization” badge."]},
  "#/policies|":{"title":"Content policies","body":"The content policies in force, updated centrally; you can view previous versions.\nFor admins: edit a policy as a new version saved as a draft, then publish it.","tips":["You get a notice when a policy is updated."]},
  "#/privacy|":{"title":"Privacy","body":"Choose how others see your profile, or make your account private.\nSet who can message you, mention you and comment on your posts: everyone, people you follow, or nobody.\nTurn on filtering for messages from people you don’t follow so they go to “Message requests”.","tips":["A private account lets you approve your followers yourself."]},
  "#/protection|":{"title":"Protection","body":"Protection mode temporarily limits who can reply, message or mention you to people you follow and long-time followers.\nIt can switch on automatically for 24 hours when an abuse wave is detected.\nManage blocked accounts and muted words and accounts, with automatic blocking of linked accounts.","tips":["A mute can be timed or permanent.","The shield (safety) button on every post opens safety tools in one tap."]},
  "#/reset|":{"title":"New password","body":"Choose a new password of at least 8 characters and type it twice to confirm.\nAfter saving, you are signed out of all other devices.","tips":["You reach this page from the reset link in your email."]},
  "#/safety-cases|":{"title":"Safety queue (staff)","body":"For the safety team: urgent reports ordered by priority.\nThe case page shows preserved evidence with its chain check, and available actions.\nReport drafts for authorities are exported as JSON for manual submission.","tips":["Nothing is sent to authorities automatically."]},
  "#/security|":{"title":"Security center","body":"Turn on two-step verification by scanning a QR code with an authenticator app, and save your backup codes.\nAdd a passkey to sign in without a password.\nReview active sessions, end any you don’t recognize, and download a copy of your data.","tips":["Each backup code works once and won’t be shown again, so save them now."]},
  "#/admin/security|":{"title":"Platform security","body":"Require two-step verification for admins and moderators after a grace period you choose.\nStaff who haven't turned it on by then act as regular members until they do; their powers return at once.\n“Sign out everyone” ends every member's sessions on every device during a security incident.","tips":["Turn on two-step verification for your own account before requiring it or signing everyone out.","No role is removed from the database."]},
  "#/settings/language|":{"title":"Interface language","body":"Choose the interface language: Arabic or English.\nPage direction follows the language, and you can switch quickly from the language button at the top.","tips":["To translate posts, open “Translation preferences”."]},
  "#/settings/translate|":{"title":"Translation preferences","body":"Turn on automatic translation of what you see, and choose the target language.\nPick languages you don’t want translated.\nMachine translation is a feature for “Mujtama AI” subscribers.","tips":["The default is your interface language."]},
  "#/versions|":{"title":"Release history","body":"See what changed in every version of Mujtama+, newest first.\nTap a version to see its details; the version you use now is marked «Current».","tips":["Open it from Settings: «Release history»."]},
  "#/share|":{"title":"Share to Mujtama+","body":"Sharing from another app opens a new post with the shared title, text and link.\nUp to 4 images are attached and uploaded once connected.","tips":["Mujtama+ appears in the share menu after you install the app."]},
  "#/staff|":{"title":"Support staff tools","body":"For moderators and admins: the support ticket queue and replies.\nThe help center article editor and ambassador application review.\nLaunch management: the waitlist and invite codes.","tips":["Never ask a user for their password or wallet phrase."]},
  "#/status|":{"title":"System status (admin)","body":"Admin only: status of services such as the database, media, realtime updates and background jobs.\nUptime, memory and response speed, plus front-end errors and real-user performance.\nFeature flags and the audit log chain check: each decision is linked to the previous one’s fingerprint.","tips":["“Check now” re-verifies the log’s integrity."]},
  "#/tickets|":{"title":"Support tickets","body":"If you hit a problem, open a ticket and the support team replies here.\nPick a subject and category, explain what happened, and attach images if needed.\nOpen any ticket to follow the thread and reply.","tips":["Say what happened, when, and what you tried.","Never write your password or wallet phrase."]},
  "#/trust|":{"title":"Trust & growth (admin)","body":"Admin only: verification requests with their documents, to approve or reject.\nImpersonation suspicions with a similarity score, to suspend the impersonator or dismiss.\nThe sign-up growth funnel and running experiments.","tips":["Verification documents are seen only by the review team."]},
  "#/unsubscribe|":{"title":"Email unsubscribe","body":"You reach this page from the one-click unsubscribe link in our emails.\nIt applies right away; you can undo or fine-tune in email preferences.","tips":["Important security alerts may continue to protect your account."]},
  "#/urgent|":{"title":"Urgent report","body":"For serious cases: danger to a child, self-harm, threats of violence, blackmail or exploitation.\nThe report goes to the safety team’s priority queue, and you follow its status here.","tips":["If there is immediate danger, call emergency services first."]},
  "#/verify|":{"title":"Verification request","body":"The badge confirms an account really is who it says: verified identity, creator, organization or expert.\nChoose the verification type and attach documents (ID, commercial registration, certificate).\nThe team reviews requests manually; you see your request’s status here.","tips":["Only the review team sees your documents; they are never shown publicly."]},
  "#/waitlist|":{"title":"Waitlist","body":"During the gradual launch, sign-up may be invite-only; the page tells you if it is open to everyone.\nHave an invite code? Enter it here, then create your account.\nOr join the waitlist with your email to receive an invite.","tips":["Your details are used only to send the invite and are deleted after the gradual launch."]},
  "#/transparency/|":{"title":"Transparency reports","body":"Aggregated numbers on reports and moderation decisions, published every month and every quarter.\nOpen a report to see reports by type, the actions taken and the appeals.\nReports never contain personal data.","tips":["“Shareable copy” opens a public link to the report that you can send to anyone."]}
};
